const lines = String(msg.payload).split(/\r?\n/).map(s => s.trim()).filter(Boolean);
if (!lines.length) { node.warn('El fichero no contiene líneas'); return null; }
const batch = 5000;
const out = [];
for (let i = 0; i < lines.length; i += batch) {
    out.push({
        method: 'POST',
        url: `${env.get('INFLUX_URL') || 'http://influxdb:8086'}/api/v2/write?org=${encodeURIComponent(env.get('INFLUX_ORG') || 'ree')}&bucket=${encodeURIComponent(env.get('INFLUX_BUCKET') || 'ree_analisis')}&precision=ns`,
        headers: {
            Authorization: `Token ${env.get('INFLUX_WRITE_TOKEN') || ''}`,
            'Content-Type': 'text/plain; charset=utf-8'
        },
        payload: lines.slice(i, i + batch).join('\n')
    });
}
node.status({fill:'blue', shape:'dot', text:`${lines.length} líneas / ${out.length} lotes`});
return [out];
